(int value) {
__asm__ volatile(
"LSR r1, r0, #24\n\t"
"AND r2, r0, #0x000000FF\n\t"
"ADD r0, r1, r2\n"
"BX lr"
);
}

Named operands
int inlineAssembly(int value)
{
int var1, var2, res;
__asm__ volatile(
"AND %[asmVar2], %[asmValue], #0x000000FF\n\t"
"LSR %[asmVar1], %[asmValue], #24\n\t"
"ADD %[asmRes], %[asmVar1], %[asmVar2]"
: [asmVar1] "=r" (var1),
[asmVar2] "=r" (var2),
[asmRes] "=r" (res)
: [asmValue] "r" (value)
);
return res;
}

Positional operands
int inlineAssembly(int value)
{
int var1, var2, res;
__asm__ volatile(
"AND %1, %3, #0x000000FF\n\t"
"LSR %0, %3, #24\n\t"
"ADD %2, %0, %1"
: "=r" (var1),
"=r" (var2),
"=r" (res)
: "r" (value)
);
return res;
}

